  const candidates=(D.travelEvents||[]).filter(e=>Math.random()<e.chance);if(candidates.length){const e=rn(candidates);if(e.cost&&s.cash>=e.cost){s.cash-=e.cost;logTransaction(-e.cost,'Travel',e.title,{account:'Checking'})}applyEffects(e.effects||{});extra=` ${e.text}`}
