  recordLife('travel',`Traveled to ${place}`,{activity:a.id,cost,destination:place,companion:mode});log(`I traveled to ${place} ${mode==='solo'?'solo':mode==='partner'?`with ${s.partner.name}`:'with family'} for ${detail}.${extra}`);addMemory(`✈️ ${place}`,`${a.label} • ${label}`,'travel');queueExperience(`✈️ ${a.label} — ${place}`,`You enjoyed ${detail}.${extra} Cost: ${money(cost)}.`,`The trip became part of my life story.`);msg('lifeActivityMessage',`${place} • ${label} • ${money(cost)}.`);return true;
