function careerUnlockNotice(before,source){const old=new Set(before||[]),opened=unlockedJobKeys().filter(k=>!old.has(k));if(!opened.length)return;const tracks=[...new Set(opened.map(k=>D.jobs[k].track))],names=opened.slice(0,3).map(k=>D.jobs[k].name);recordLife('careerUnlock',`New career path${tracks.length>1?'s':''} opened`,{source,tracks,jobs:opened});queueExperience('🔓 New Career Path Available',`${source} opened ${tracks.join(', ')} opportunities. ${names.join(', ')}${opened.length>3?' and more':''} are now available in the Job Market.`,'New qualifications expanded my career options.');}
