  $('acceptPromotionBtn').onclick=()=>{const o=s.pendingPromotionOffer;if(!o)return;const old=D.jobs[o.fromJob||s.job],next=D.jobs[o.jobKey],company=s.company;closeCareerRecord('Promoted');s.job=o.jobKey;s.salary=o.offer;s.jobStartingSalary=o.offer;s.performance=D.balance.career.promotion.promotionPerformance;s.jobYears=0;s.careerReputation=clamp((s.careerReputation||0)+5);s.pendingPromotionOffer=null;startCareerRecord(s.job,company,s.salary);recordLife('promotion',`Promoted to ${next.name}`,{from:old?.name||'Previous role',salary:s.salary,company});log(`Promoted within ${company} to ${next.name} at ${money(s.salary)} per year.`);queueExperience('🎉 Promotion Accepted',`${company} promoted you from ${old?.name||'your previous role'} to ${next.name}. Your new salary is ${money(s.salary)} per year.`,'I advanced within the same company.');commit()};
