  $('housingBtn').onclick=()=>{const key=$('housingSelect').value,h=D.housing[key],current=D.housing[s.housing];if(s.age<h.minAge)return msg('housingMessage','Too young for that housing option.');if(current?.owned&&key!==s.housing)return msg('housingMessage','Sell your current home before moving or buying another property.');if(key===s.housing)return msg('housingMessage',`You already live in ${h.name}.`);if(key==='parents'){s.housing='parents';s.homePurchasePrice=0;log(`Age ${s.age}: Moved in with family.`);commit();return}if(!h.owned){s.housing=key;s.homePurchasePrice=0;log(`Age ${s.age}: Moved into an apartment.`);commit();return}const price=housingMarketPrice(key),mort=D.balance.yearly.finance.mortgage,down=Math.round(price*mort.downPayment);if((s.credit||0)<620)return msg('housingMessage','Credit 620+ required.');if(s.cash<down)return msg('housingMessage',`Need ${money(down)} for the down payment.`);s.cash-=down;logTransaction(-down,'Housing',`${h.name} down payment`,{account:'Checking'});s.housing=key;s.homeUpgrades=[];s.homePurchasePrice=price;s.mortgageBalance=price-down;s.mortgageRate=s.economy.interest+mort.rateSpread;s.mortgageYearsRemaining=mort.termYears;s.credit=Math.max(300,s.credit-12);s.stats.homesOwned++;recordLife('homePurchase',`Bought ${h.name}`,{price,down});log(`Age ${s.age}: Bought a ${h.name} for ${money(price)} with ${money(down)} down.`);msg('housingMessage',`Home purchased. Mortgage: ${money(s.mortgageBalance)} at ${(s.mortgageRate*100).toFixed(2)}%.`);commit()};
  $('payMortgageBtn').onclick=()=>{if(!(s.mortgageBalance>0))return msg('housingMessage','Your home has no mortgage balance.');const a=Math.min(s.cash,s.mortgageBalance,transferOption('mortgageAmountSelect','mortgageCustomAmount',s.mortgageBalance));if(a<=0)return msg('housingMessage','Choose a valid payment amount and make sure you have enough cash.');s.cash-=a;s.mortgageBalance=Math.max(0,s.mortgageBalance-a);logTransaction(-a,'Housing','Extra mortgage payment',{account:'Checking'});if(s.mortgageBalance<=0){s.mortgageBalance=0;s.mortgageYearsRemaining=0;msg('housingMessage','Mortgage paid off!')}else msg('housingMessage',`${money(a)} paid toward the mortgage. ${money(s.mortgageBalance)} remaining.`);commit()};
  $('sellHomeBtn').onclick=()=>{const h=D.housing[s.housing];if(!h?.owned)return msg('housingMessage','You do not currently own a home to sell.');const value=homeValue(),cost=Math.round(value*(D.balance.yearly.finance.mortgage.saleCost||.06)),net=Math.round(value-cost-(s.mortgageBalance||0));if(!riskyConfirm(`Sell ${h.name} for about ${money(value)}? Selling costs are about ${money(cost)}.`))return;if(net>=0){s.cash+=net;logTransaction(net,'Housing',`Sold ${h.name}`,{account:'Checking'})}else{s.debt+=Math.abs(net);logTransaction(-Math.abs(net),'Debt',`Home sale deficiency — ${h.name}`,{account:'Debt'})}log(`Age ${s.age}: Sold ${h.name} for ${money(value)}${net>=0?`, receiving ${money(net)} after mortgage and selling costs`:` and owed ${money(Math.abs(net))} after the sale`}.`);s.housing='parents';s.homeUpgrades=[];s.homePurchasePrice=0;s.mortgageBalance=0;s.mortgageRate=0;s.mortgageYearsRemaining=0;msg('housingMessage',net>=0?`${money(net)} added to Checking after the sale.`:'The sale deficiency was added to debt.');commit()};
