  $('dateBtn').onclick=()=>{const r=R.date,miss=missingRequirements(r.requirements||[]);if(miss.length)return msg('relationshipMessage',`Locked: ${miss.join(' • ')}.`);if(!actionCost('dating',r.ap))return;const chance=(s.looks+s.social+s.happiness)/330+s.hidden.luck/1000;if(Math.random()<chance){const minPartnerAge=s.age>=18?18:r.minAge,pref=s.datingPreference||'Anyone',gender=pref==='Women'?'Female':pref==='Men'?'Male':(Math.random()<.5?'Female':'Male'),pool=gender==='Female'?(D.names.female||D.names.adults):(D.names.male||D.names.adults);s.partner=npc(generatePersonName(gender,'adult'),'Partner',Math.max(minPartnerAge,s.age+Math.floor(rand(-3,4))),r.startQuality,gender);s.relationship='Dating';stat('happiness',r.happiness);log(`Age ${s.age}: Started dating ${s.partner.name}.`);msg('relationshipMessage',`You started dating ${s.partner.name}.`)}else msg('relationshipMessage','No luck this time.');commit()};
